using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static void AssertQuote(string subtotal, LoyaltyTier tier, string? code, string? discount, string? total)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(Money.Cents(subtotal), tier, code));

        if (discount is not null) Assert.Equal(Money.Cents(discount), quote.DiscountCents);
        if (total is not null) Assert.Equal(Money.Cents(total), quote.TotalCents);
    }

    // Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, "5.00", "95.00")]
    [InlineData(LoyaltyTier.Silver, "10.00", "90.00")]
    [InlineData(LoyaltyTier.Gold, "15.00", "85.00")]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier tier, string discount, string total) =>
        AssertQuote("100.00", tier, null, discount, total);

    // The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData("200.00", LoyaltyTier.Gold, "20.00", "180.00")]
    [InlineData("300.00", LoyaltyTier.Silver, "20.00", "280.00")]
    [InlineData("120.00", LoyaltyTier.Gold, "18.00", "102.00")]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(subtotal, tier, null, discount, total);

    // No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData("29.99", "0.00", "29.99")]
    [InlineData("30.00", "4.50", "25.50")]
    public void S3_NoLoyaltyDiscountUnderThirtyEuros(string subtotal, string discount, string total) =>
        AssertQuote(subtotal, LoyaltyTier.Gold, null, discount, total);

    // The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "15.00", "85.00")]
    [InlineData("20.00", LoyaltyTier.Bronze, "5.00", "15.00")]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    // The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData("200.00", LoyaltyTier.Gold, "25.00", "175.00")]
    [InlineData("300.00", LoyaltyTier.Silver, "25.00", "275.00")]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, total);

    // Promo codes ignore case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        AssertQuote("100.00", LoyaltyTier.Silver, code, "15.00", null);

    // The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "19.00", "81.00")]
    [InlineData("300.00", LoyaltyTier.Bronze, "30.00", "270.00")]
    [InlineData("20.00", LoyaltyTier.Gold, "2.00", "18.00")]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMostFifteenEuros(string subtotal, LoyaltyTier tier, string discount, string total) =>
        AssertQuote(subtotal, tier, "SUMMER10", discount, total);

    // An unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote("100.00", LoyaltyTier.Silver, "SPRING", "10.00", "90.00");

    // Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData("100.00", "20.00", "80.00")]
    [InlineData("50.00", "10.00", "40.00")]
    [InlineData("200.00", "20.00", "180.00")]
    public void S9_PlatinumMembersReceiveTwentyPercentLoyaltyDiscount(string subtotal, string discount, string total) =>
        AssertQuote(subtotal, LoyaltyTier.Platinum, null, discount, total);

    // The discount never exceeds the subtotal
    [Theory]
    [InlineData("4.00", LoyaltyTier.Bronze, "4.00")]
    [InlineData("3.00", LoyaltyTier.Gold, "3.00")]
    public void S10_DiscountNeverExceedsTheSubtotal(string subtotal, LoyaltyTier tier, string discount) =>
        AssertQuote(subtotal, tier, "WELCOME5", discount, "0.00");
}
E
cat > tests/CheckoutPricing.UnitTest/Features/Shipping/CalculateShippingFeeAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Shipping;

public class CalculateShippingFeeAcceptanceTests
{
    private static int Fee(string total, LoyaltyTier tier, bool express) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Money.Cents(total), tier, express));

    // Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData("49.99", LoyaltyTier.Bronze, "4.90")]
    [InlineData("50.00", LoyaltyTier.Bronze, "0.00")]
    [InlineData("49.99", LoyaltyTier.Silver, "4.90")]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, false));

    // Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumMembersNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(Money.Cents("0.00"), Fee("10.00", tier, false));

    // Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData("100.00", LoyaltyTier.Bronze, "9.90")]
    [InlineData("10.00", LoyaltyTier.Gold, "9.90")]
    [InlineData("10.00", LoyaltyTier.Platinum, "0.00")]
    public void S13_ExpressShippingCostsNinetyNineButIsFreeForPlatinumOnly(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, true));
}
E
cat > tests/CheckoutPricing.UnitTest/Features/CheckoutQuote/QuoteCheckoutAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.CheckoutQuote;

public class QuoteCheckoutAcceptanceTests
{
    // The checkout quote adds shipping to the payable total
    [Theory]
    [InlineData("100.00", LoyaltyTier.Silver, "WELCOME5", false, "85.00", "0.00", "85.00")]
    [InlineData("50.00", LoyaltyTier.Bronze, null, false, "47.50", "4.90", "52.40")]
    [InlineData("200.00", LoyaltyTier.Platinum, "SUMMER10", true, "165.00", "0.00", "165.00")]
    [InlineData("20.00", LoyaltyTier.Gold, null, true, "20.00", "9.90", "29.90")]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        string subtotal, LoyaltyTier tier, string? code, bool express, string payable, string fee, string total)
    {
        var quote = new QuoteCheckout().Handle(new QuoteCheckoutQuery(Money.Cents(subtotal), tier, code, express));

        Assert.Equal(Money.Cents(payable), quote.PayableCents);
        Assert.Equal(Money.Cents(fee), quote.ShippingCents);
        Assert.Equal(Money.Cents(total), quote.TotalCents);
    }
}
