using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest;

public class CalculateShippingFeeAcceptanceTests
{
    private static int Fee(string total, LoyaltyTier tier, bool express) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(Money.Cents(total), tier, express));

    // Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData("49.99", LoyaltyTier.Bronze, "4.90")]
    [InlineData("50.00", LoyaltyTier.Bronze, "0.00")]
    [InlineData("49.99", LoyaltyTier.Silver, "4.90")]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, false));

    // Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumMembersNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(Money.Cents("0.00"), Fee("10.00", tier, false));

    // Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData("100.00", LoyaltyTier.Bronze, "9.90")]
    [InlineData("10.00", LoyaltyTier.Gold, "9.90")]
    [InlineData("10.00", LoyaltyTier.Platinum, "0.00")]
    public void S13_ExpressShippingCostsNinetyNineButIsFreeForPlatinumOnly(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Money.Cents(fee), Fee(total, tier, true));
}

